class Solution {
    public boolean subsetSumExists(int[] nums, int target) {
        return search(nums, 0, target);
    }

    private boolean search(int[] nums, int index, int remaining) {
        if (remaining == 0) {
            return true;
        }
        if (index == nums.length) {
            return false;
        }
        if (search(nums, index + 1, remaining - nums[index])) {
            return true;
        }
        return search(nums, index + 1, remaining);
    }
}

class Solution {
    public boolean subsetSumExists(int[] nums, int target) {
        return dfs(nums, 0, 0, target);
    }

    private boolean dfs(int[] nums, int index, int currentSum, int target) {
        if (currentSum == target) {
            return true;
        }
        if (index == nums.length) {
            return false;
        }
        if (dfs(nums, index + 1, currentSum + nums[index], target)) {
            return true;
        }
        return dfs(nums, index + 1, currentSum, target);
    }
}

class Solution {
    public boolean subsetSumExists(int[] nums, int target) {
        int total = 1 << nums.length;
        for (int mask = 0; mask < total; mask++) {
            int sum = 0;
            for (int i = 0; i < nums.length; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += nums[i];
                }
            }
            if (sum == target) {
                return true;
            }
        }
        return false;
    }
}

